    static let pumpkinFieldNight = SmallCases.make(
        key: "story.followup.pumpkinFieldNight",
        category: .property,
        headlines: ["Man Hauls Pumpkins From Field After Dark"],
        law: "misdLarceny",
        spec: "Stole pumpkins valued at $340 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} loaded pumpkins from a field at night.",
        state: [E(.video, 3, "Field Camera", "{D} fills a truck.")],
        defense: [E(.statement, 1, "Gleaning", "{DL} says the field was picked.")],
        role: "Farmer",
        exam: [.direct("What is your farm?", "\"I run a pumpkin farm, with several acres of pumpkins that I sell to stands, schools, and visitors in the fall.\""), .direct("What did you find that morning?", "\"Wide tire tracks in the field and a large patch of the crop missing, with stems and vines left behind.\""), .direct("How much was taken?", "\"About three hundred forty dollars' worth, roughly sixty large pumpkins from the best part of the field.\""), .direct("What does the field camera show?", "\"A pickup backing into the field at night, a person loading pumpkins by hand, and the truck leaving with a full bed.\""), .direct("Who was it?", "\"The plate is partly visible on the camera, and it matches a truck registered to {DL}.\""), .direct("What did {DL} say?", "\"{D.He} said the field had been picked and that leftover pumpkins were fair to take.\""), .cross("Fields are sometimes gleaned after harvest?", "\"Some farmers allow it, but only with their permission.\""), .cross("This field hadn't been harvested?", "\"Not fully. I was still selling from it on weekends.\""), .cross("There was no sign saying you could take them?", "\"No, if anything there was a sign saying the farm was closed at night.\""), .cross("{DL} didn't damage the vines?", "\"{D.He} left stems and some vines, but I wouldn't call it destruction.\""), .cross("You didn't see {DL} in the field?", "\"No, only on the video and by the tracks.\"")],
        theory: ("{D} took pumpkins.", "Gleaning."),
        allocution: "\"I loaded those pumpkins at night because I believed the field had already been picked and the rest were left to rot. I should have found the farmer and asked. I understand now that the ones I took were still {V.his} harvest to sell. I'm sorry for that loss, and I'll pay the farmer whatever they were worth.\"",
        truths: ("The field had not been picked.", "{DL} sold pumpkins roadside."),
        defendant: [.direct("Did you take pumpkins from the field?", "\"Yes, I took a truckload of pumpkins that I thought were leftovers after the main harvest.\""), .direct("Why did you think they were leftovers?", "\"The field looked picked over, and I'd seen people pick pumpkins there before. I assumed it was allowed.\""), .direct("Did you ask the farmer?", "\"No. It was night and I didn't want to wake anyone. I should have asked.\""), .direct("What did you plan to do with them?", "\"I was going to give some to my church and sell a few to pay for gas.\""), .direct("What did you do when the deputy called?", "\"I admitted it and told him where the pumpkins were. I offered to pay for them.\""), .direct("What would you tell the farmer?", "\"I'm sorry for taking from your field without asking. I'll pay the three hundred forty dollars.\""), .cross("You took pumpkins from a field before, didn't you?", "\"Yes, and I was told to ask first. I should have remembered that.\""), .cross("You came at night with a truck?", "\"I did, and that makes it look planned, though I only wanted to avoid the weekend crowd.\""), .cross("You've given some away already?", "\"A few, and I can list who got them.\""), .cross("You'll pay the full price?", "\"Yes, I'll pay the three hundred forty dollars today, if the farmer will take it from me.\""), .cross("You'll stay off the farm?", "\"Yes, I'll stay off the farm unless the farmer invites me to buy pumpkins in the daytime.\"")],
        openings: ("A pumpkin farmer found wide tire tracks in the field and a large patch of the crop missing, with stems and vines left behind, and a field camera shows {D} filling a truck at night, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say the field had already been picked, and {D} was gleaning what was left behind, which farmers often allow. {D} did not think the pumpkins belonged to anyone."),
        closings: ("The camera shows {D} filling a truck at night from {V}'s field, and after {PRIOR} {DL} understood exactly whose pumpkins they were and when they were meant to be picked.", "Gleaning a picked field is a common practice, and a camera at night cannot tell what was left. The State must prove {D} took pumpkins that had not been abandoned."),
        timeline: [(0, "Night: the headlights."), (0, "Dawn: bare rows.")],
        identified: "Field Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let ladderAgain = SmallCases.make(
        key: "story.followup.ladderAgain",
        category: .property,
        headlines: ["Ladder Taken From Second Job Site"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a contractor, valued at $280, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took a ladder from another job site.",
        state: [E(.video, 3, "Site Camera", "{D} lifts the ladder.")],
        defense: [E(.statement, 1, "Borrow", "{DL} says {D.he} meant to return it.")],
        role: "Contractor",
        exam: [.direct("What is your business?", "\"I'm a general contractor, and I run several small jobs at the same time with my own tools and ladders.\""), .direct("What was taken?", "\"A tall extension ladder worth about two hundred eighty dollars, left against the side of a house I was working on.\""), .direct("What does the site camera show?", "\"{DL} walking up the driveway, lifting the ladder off the wall, and carrying it to a truck at the curb.\""), .direct("How did you know {DL}?", "\"{DL} works for a competing contractor who has a job down the street.\""), .direct("Did you give permission?", "\"No. I'd never given {D.him} permission, and we've never shared equipment.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} meant to return it after using it for one job.\""), .cross("The ladder was returned?", "\"Yes, two days later, left leaning against my truck.\""), .cross("The ladder was damaged?", "\"No, it came back clean and straight, and nothing on it was bent or broken.\""), .cross("{DL} didn't try to hide?", "\"No, {D.he} walked right up the driveway in broad daylight and carried it away.\""), .cross("Contractors do borrow tools sometimes?", "\"Sometimes they do, but in my experience they ask first before they touch anything.\""), .cross("{DL} never called you?", "\"No, {D.he} never called me, not before taking it and not after bringing it back.\"")],
        theory: ("{D} took a ladder.", "A borrow."),
        allocution: "\"I borrowed that ladder from the job site because mine was at another house, and I meant to bring it back by the end of the day. I never asked the contractor, and that was wrong of me. A tool is a living for people in the trades. I'm sorry for the trouble it caused, and I'll replace anything that was damaged.\"",
        truths: ("{DL} asked no one.", "The ladder was marked."),
        defendant: [.direct("Did you take the ladder?", "\"Yes, I took it. Mine had broken the day before, and I needed one to finish a roof repair.\""), .direct("Why didn't you ask?", "\"I couldn't find the owner, and the job was urgent. I told myself I'd bring it back by evening.\""), .direct("When did you return it?", "\"Two days later. The job ran longer than I planned, and I left it by {V.his} truck.\""), .direct("Did you mean to keep it?", "\"No. I never planned to keep it. I'm a contractor, and I know how much a good ladder costs.\""), .direct("What did you do when you heard he'd reported you?", "\"I told the deputy I'd already returned it, and I apologized.\""), .direct("What would you tell the contractor?", "\"I'm sorry for taking the ladder without asking. I'll pay a rental fee for the two days.\""), .cross("You've been accused of taking equipment from other jobs before, haven't you?", "\"Yes, and I said I'd always ask. I didn't ask this time.\""), .cross("You carried it to your truck in daylight?", "\"I did, because I thought it was fine to borrow it.\""), .cross("You know it wasn't yours?", "\"I do, and I should have waited for {V.him}.\""), .cross("You'll pay for the use?", "\"Yes, I'll pay fifty dollars for the two days and buy a new strap for it.\""), .cross("You'll buy your own ladder?", "\"Yes, I'll buy one this week so I never have to take anyone else's again.\"")],
        openings: ("A general contractor running several small jobs found that a tall extension ladder worth about $280, left against the side of a house he was working on, was gone, and the site camera shows {D} lift the ladder, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} meant to return the ladder after borrowing it for a job, as tradesmen often do. {D} did not mean to keep it."),
        closings: ("The camera shows {D} lift the ladder from the site and leave, and with {PRIOR} behind {D.him}, {DL} knew what taking a tradesman's tool means.", "Tradesmen borrow ladders from each other, and {D} meant to return it. The State must prove {D} meant to keep it permanently."),
        timeline: [(0, "Noon: break."), (0, "12:30 p.m.: gone.")],
        identified: "Site Camera",
        mood: .indifferent)

    static let leashTagScam = SmallCases.make(
        key: "story.followup.leashTagScam",
        category: .whiteCollar,
        headlines: ["Woman Sells Fake Pet Registration Door to Door"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $55, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold fake pet registrations door to door.",
        state: [E(.physical, 3, "Forms", "Forms with no county stamp.")],
        defense: [E(.statement, 1, "Real", "{DL} says they were real.")],
        role: "Homeowner",
        exam: [.direct("What happened at your door?", "\"A man came to my door with a clipboard, saying the county now required a registration for every pet, and that {D.he} could do it for me.\""), .direct("What did {D.he} offer?", "\"A pet registration form and a tag, for fifty-five dollars, and {D.he} said I'd be fined if I didn't have one.\""), .direct("What did you do?", "\"I paid cash, and {D.he} gave me a form and a tag with my dog's name on it.\""), .direct("What did you learn later?", "\"The county animal office told me the form was not theirs, and there's no such door-to-door program.\""), .direct("What do the forms show?", "\"They have no county stamp, no registration number, and a logo that looks copied from the county website.\""), .direct("What did {DL} say?", "\"{D.He} said the forms were real and that {D.he} had been told to sell them by a group.\""), .cross("The tag was a real pet tag?", "\"It's a regular metal tag, but it has no county mark.\""), .cross("{DL} was polite?", "\"Very, and {D.he} wore a lanyard that looked official.\""), .cross("Other neighbors paid?", "\"I heard from two other neighbors who paid the same fifty-five dollars for the same forms.\""), .cross("You didn't ask for ID?", "\"I asked, and {D.he} showed a card that looked like a badge.\""), .cross("You've gotten no refund?", "\"No, I haven't gotten a refund, and I haven't seen {D.him} on our street since.\"")],
        theory: ("{D} sold fake forms.", "Real forms."),
        allocution: "\"I really did think those pet registrations were legitimate. I bought the packets online and sold them door to door, and I never knew they had no value. I'm sorry to every homeowner who paid fifty-five dollars for a tag that meant nothing. I'll refund each of them, and I'll check anything I sell more carefully.\"",
        truths: ("The county never issued them.", "{DL} had 300."),
        defendant: [.direct("Did you sell registrations?", "\"Yes, I sold them door to door. A friend told me it was a legitimate side job for a pet group.\""), .direct("Who gave you the forms?", "\"A man who said {D.he} ran a pet services group. I didn't ask for a license or paperwork.\""), .direct("Did you know they weren't from the county?", "\"I thought they were official because the form looked official. I didn't check with the county.\""), .direct("What did you do with the money?", "\"I kept a share and gave the rest to the man. I made about two hundred dollars.\""), .direct("What did you do when the deputy called?", "\"I told {OFF.him} who gave me the forms and gave {OFF.him} my notes. I stopped selling.\""), .direct("What would you tell the homeowners?", "\"I'm sorry for taking your money. I'll refund every dollar and give the deputy all my records.\""), .cross("You've been charged with selling something that wasn't what you claimed before, haven't you?", "\"Yes, and the judge told me to be careful, and I wasn't. I trusted the wrong person.\""), .cross("You said the county required it?", "\"I did, because that's what I was told. I should have checked.\""), .cross("You wore a lanyard that looked official?", "\"The man gave it to me, and I wore it. I know it was misleading.\""), .cross("You'll refund the families?", "\"Yes, I'll refund the families, and I have a list of every house I visited.\""), .cross("You'll stop door-to-door work?", "\"Yes, completely. I won't go door to door for any group again.\"")],
        openings: ("A man came to {V}'s door with a clipboard saying the county required a registration for every pet, and charged $55 for a form and a tag and said {V} would be fined without one, and the forms carry no county stamp, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the forms were real and {D} believed the county required them. {D} did not mean to deceive anyone."),
        closings: ("The forms carry no county stamp, the county issues no such tag, and after {PRIOR} {DL} knew exactly what a real registration looks like.", "A person who believes a form is real has not committed fraud. The State must prove {D} knew the forms were fake when {D.he} sold them."),
        timeline: [(0, "Morning: knock."), (1, "County says no.")],
        identified: "Forms",
        mood: .indifferent,
        genders: ["D": .female])

    static let chemHedge = SmallCases.make(
        key: "story.followup.chemHedge",
        category: .publicOrder,
        headlines: ["Man Sprays Brush Killer on Neighbor's Hedge"],
        law: "disorderly",
        spec: "Willfully injured property of {V}, a neighbor, with chemicals, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sprayed brush killer on a neighbor's hedge.",
        state: [E(.video, 3, "Porch Camera", "{D} sprays the hedge.")],
        defense: [E(.statement, 1, "Drift", "{DL} says wind blew it.")],
        role: "Neighbor",
        exam: [.direct("What happened to your hedge?", "\"It turned brown and died over about a week, in a long row along the property line that I'd planted ten years ago.\""), .direct("What did you find?", "\"A strong chemical smell and dead grass at the base of the hedge, with a trail of dead plants along the line.\""), .direct("What does your porch camera show?", "\"{DL}, my neighbor, spraying the hedge with a pump sprayer one evening, working along the whole row.\""), .direct("What was the damage?", "\"About eight hundred dollars to remove the dead hedge and replant, plus the loss of privacy.\""), .direct("What was the dispute?", "\"{DL} said the hedge blocked {D.his} light and was on {D.his} side of the line, though my survey shows otherwise.\""), .direct("What did {DL} say?", "\"{D.He} said the wind blew the spray onto the hedge while {D.he} was killing weeds.\""), .cross("There are weeds along the line?", "\"Some, along the fence, and {DL} has complained to me about them more than once.\""), .cross("The spray was brush killer?", "\"A label on a container found in {D.his} garage says it's brush killer.\""), .cross("{DL} sprayed only along the hedge?", "\"The video shows {D.him} spraying the base of the hedge, not the weeds in the middle of the yard.\""), .cross("Wind was blowing that night?", "\"A light breeze, but not enough to carry spray along a row.\""), .cross("You told {DL} to stop?", "\"I'd told {D.him} many times to leave the hedge alone.\"")],
        theory: ("{D} killed a hedge.", "Drift."),
        allocution: "\"I sprayed brush killer along my own side of the property line, and the wind may have carried it onto the hedge. I never meant to hurt my neighbor's plants, and I'm sorry they browned. I should have waited for a calm day. I'll replace the hedge, and I'd like us to get along.\"",
        truths: ("The line is straight.", "The day was calm."),
        defendant: [.direct("Did you spray the hedge?", "\"I sprayed near the hedge to kill weeds, and some of the spray drifted onto the leaves.\""), .direct("Did you aim at the hedge?", "\"No. I aimed at weeds along the fence. I didn't think the spray would carry that far.\""), .direct("Was it windy?", "\"There was a breeze, and I should have waited for a calmer night.\""), .direct("Did you want the hedge gone?", "\"I was annoyed by it, but I wouldn't kill it. I only wanted weeds out.\""), .direct("What did you do when the hedge died?", "\"I told my neighbor I was sorry and offered to pay for new plants.\""), .direct("What would you tell the neighbor?", "\"I'm sorry about the hedge. I'll pay for replacements and plant them myself if you prefer.\""), .cross("You've argued about this hedge for years, haven't you?", "\"Yes, and I should have tried harder to settle it.\""), .cross("The video shows you spraying along the whole row?", "\"It does show that, and I understand how that looks to someone who owns the hedge.\""), .cross("Brush killer is meant for large woody plants?", "\"Yes, and I shouldn't have used it near the hedge.\""), .cross("You'll pay eight hundred dollars?", "\"Yes, I'll pay the eight hundred dollars in installments over the next few months.\""), .cross("You'll stay off your neighbor's line?", "\"Yes, and I'll go through a lawyer for any dispute.\"")],
        openings: ("A hedge along the property line that {V} had planted ten years earlier turned brown and died over about a week, with a strong chemical smell and a trail of dead plants along the line, and a porch camera shows {D} spray it, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {D} sprayed brush killer on {D.his} own side and the wind carried it onto the hedge. Drift is an accident and not an act of destruction."),
        closings: ("The camera shows {D} spray the chemical along the line, the hedge died a week later, and with {PRIOR} already on {D.his} record, {DL} knew exactly what the brush killer does to a hedge.", "Drift in the wind is a risk of any spraying, and {D} did not aim at the hedge. The State must prove {D} meant to kill it."),
        timeline: [(0, "Morning: spray."), (2, "The hedge dies.")],
        identified: "Porch Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let pewAgain = SmallCases.make(
        key: "story.followup.pewAgain",
        category: .violent,
        headlines: ["Congregant Pushes Greeter Over Parking"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shoved a greeter at a church lot.",
        state: [E(.video, 3, "Lot Camera", "{D} pushes {V}.")],
        defense: [E(.statement, 1, "Reserved", "{DL} says the space was {D.his}.")],
        role: "Pastor",
        exam: [.direct("What is your role at the church?", "\"I'm the pastor, and I was in the parking lot greeting people after the service.\""), .direct("What happened?", "\"{DL} pulled into a space near the entrance that was reserved for guests, and an usher asked {D.him} to move.\""), .direct("What did {DL} do?", "\"{D.He} stepped out, argued with the usher, and then shoved {V.him} backward into a car door.\""), .direct("What does the lot camera show?", "\"{DL} getting out of the car, stepping toward the usher, and pushing {V.him} hard in the chest.\""), .direct("Was the usher hurt?", "\"{V.He} had a bruise on the back and a sore shoulder, and {V.he} was upset, but {V.he} didn't need a doctor.\""), .direct("What did {DL} say?", "\"{D.He} said the space was {D.his} and that {D.he} had parked there for years.\""), .cross("The space is reserved?", "\"Yes, with a sign for guests and the elderly.\""), .cross("{DL} has attended our church?", "\"Yes, {D.he} attended our church for a few years, though not recently.\""), .cross("{DL} left right after?", "\"{D.He} drove off before the deputy arrived, and we gave the plate to the sheriff's office.\""), .cross("The usher spoke politely?", "\"Yes, {V.he} asked calmly and politely, and there was no raised voice from {V.him}.\""), .cross("Other members saw it?", "\"Several members saw it from the steps, and they were upset and called me over.\"")],
        theory: ("{D} shoved a greeter.", "A claimed space."),
        allocution: "\"I shoved that greeter in the church lot because I felt crowded, and I lost my temper. I'm ashamed to have done that on church grounds to someone who was only welcoming people. I've apologized to my pastor and I want to do it to the greeter, too. It will not happen again.\"",
        truths: ("Spaces are not reserved.", "{V} asked politely."),
        defendant: [.direct("Did you push the usher?", "\"Yes, I pushed {V.him}. I was angry that {V.he} told me to move, and I reacted without thinking.\""), .direct("Why were you angry?", "\"I'd been parking in that spot for years, and I thought it was mine. No one had told me it was reserved.\""), .direct("Did you mean to hurt {V.him}?", "\"No. I meant to move {V.him} away from my car. I didn't mean {V.him} to hit the door.\""), .direct("What did you do afterward?", "\"I drove home and felt terrible. I called the church to apologize, but no one answered.\""), .direct("What did the deputy say?", "\"{V.He} told me I shouldn't push anyone, and that I should apologize in person.\""), .direct("What would you tell the usher and the pastor?", "\"I'm sorry for losing my temper. I'll apologize in person and pay any costs.\""), .cross("You've been in trouble for pushing someone before, haven't you?", "\"Yes, and I promised to walk away. I failed.\""), .cross("The usher was elderly?", "\"Yes, {V.he}'s in {V.his} seventies, and I regret that I pushed a man {V.his} age.\""), .cross("You could have moved your car?", "\"I could have moved the car to a different space, and I should have done that.\""), .cross("You'll apologize in person?", "\"Yes, if {V.he}'ll allow me to, I'll apologize to {V.him} in person and to the pastor.\""), .cross("You'll stay out of that lot?", "\"Yes, I'll stay out of that lot unless the pastor asks me to come back.\"")],
        openings: ("The pastor, greeting people in the parking lot after the service, saw {D} pull into a space near the entrance reserved for guests, was asked by an usher to move, and the lot camera shows {D} push {V}, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the space was {D}'s, a space {D} has parked in for years, and {D} pushed only to keep it. {D} did not mean to hurt the greeter."),
        closings: ("The camera shows {D} push the usher after being asked to move, and having faced {PRIOR} before, {DL} understood exactly where a space dispute can lead.", "A man claiming a space he thinks is his is acting from a mistaken belief, not malice. The State must prove {D} meant to push {V}."),
        timeline: [(0, "10 a.m.: request."), (0, "10:01 a.m.: shove.")],
        identified: "Lot Camera",
        mood: .indifferent)

    static let brunchCarryout = SmallCases.make(
